class Example {
    int id;

    Example(int id) {
        this.id = id;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof Example)) {
            return false;
        }
        return this.id == ((Example) o).id;
    }

    public static void main(String[] args) {
        Example a = new Example(1);
        Example b = new Example(1);
        System.out.println(a.equals(b) + " " + (a == b) + " " + a.equals(a) + " " + a.equals(null));
    }
}

